arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Content-Type: application/json" -d '{"token":"***","limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for u in d.get('members',[]):
    if u.get('is_bot') or u.get('is_app_user'):
        continue
    n=(u.get('real_name') or u.get('profile',{}).get('display_name') or '')
    if 'priya' in n.lower():
        print(u['id'], n, u.get('profile',{}).get('display_name'))
"

